from lxml import etree as ET
import re
from taf.analyzer.base import LogReader
from taf.analyzer.pdml.pdml_log_entry import PdmlLogEntry
from taf.analyzer.pdml.packet import Packet


def _new_tag(element):
    """
    This method is used to return the dictionary of pdml log entries.

        :param element: takes pdml element as input
        :return: element of a dictionary
    """

    def from_name(element):
        """
        This method will derive a new tag name from the "name" attribute of the provided element.

        "If the 'name' attribute of the 'element' parameter starts with a digit, then the returned tag
        will have a "_" prepended (because XML tags are not allowed to start with a digit)."

        :param element: takes pdml element as input
        :return: returns a new XML tag of type str
        :rtype: str
        """
        name = element.get("name")
        if not name:
            return "_"
        elif name[0].isdigit():
            return "_" + name
        else:
            return name

    return {'pdml': lambda element: "root",
            'packet': lambda element: "packet",
            'proto': lambda element: from_name(element),
            'field': lambda element: from_name(element)}[element.tag](element)


class PdmlReader(LogReader):

    def __init__(self, invalid_value_handler=None, **kwargs):
        super(PdmlReader, self).__init__(**kwargs)
        if invalid_value_handler is None:
            def invalid_value_handler_function(x):
                return b"[invalid]"

            invalid_value_handler = invalid_value_handler_function
        self._invalid_value_handler = invalid_value_handler

    def _replace_show(self, value):
        try:
            ET.fromstring(b'<a show="' + value + b'"/>')
        except ET.XMLSyntaxError:
            value = self._invalid_value_handler(value)
        return value

    def _create_pdml_log_entry(self, packet_string):
        try:
            packet = ET.fromstring(packet_string)
        except ET.XMLSyntaxError:
            packet_string = re.sub(
                br'(<field[^\n]* show=")(.*?)("(?:/>|>| value| hide| showname| size| unmaskedvalue| pos))',
                lambda m: m.group(1) + self._replace_show(m.group(2)) + m.group(3),
                packet_string,
                flags=re.S)
            packet = ET.fromstring(packet_string)
        for element in packet.iter(tag=ET.Element):
            element.tag = _new_tag(element)
            for attr_name in ("name", "size", "pos", "unmaskedvalue", "hide"):
                if attr_name in element.attrib:
                    del element.attrib[attr_name]
        pkt = Packet(xml_packet=packet)
        return PdmlLogEntry.parse(timezone=self._timezone, packet=pkt)

    def __iter__(self):
        """
        Iterate through pdml log entries.

        :return: yield a PdmlLogEntry
        """
        self._inside_packet = False
        self._lines = []

        for line in self._file_obj:
            if self._inside_packet:
                self._lines.append(line)
                if b"</packet>" in line:
                    self._inside_packet = False
                    packet_string = b"".join(self._lines)
                    yield self._create_pdml_log_entry(packet_string)
            else:
                if b"<packet>" in line:
                    self._lines = [line]
                    self._inside_packet = True
